!set variable_substitution=false;
-- Update the File Copy Control Key for all records
UPDATE UTIL.tmp_ADF_SQLDB_COPY_CONTROL
SET ADF_SQLDB_COPY_CONTROL_KEY = UTIL.FXN_ARRAY_HASH([SOURCE_DATABASE_NAME, SOURCE_SCHEMA_NAME, SOURCE_TABLE_NAME])
;

-- Check for invalid/duplicated records in temp table before merging
EXECUTE IMMEDIATE $$
DECLARE
  dup_primary_key_exception EXCEPTION (-20001, 'DUPLICATE Primary Keys Detected.');
  dup_unique_key_exception EXCEPTION (-20002, 'DUPLICATE Unique Keys Detected.');
  dup_count INTEGER;
BEGIN
    SELECT COUNT(1) INTO :dup_count 
        FROM(SELECT ADF_SQLDB_COPY_CONTROL_KEY, COUNT(1) FROM UTIL.TMP_ADF_SQLDB_COPY_CONTROL GROUP BY ADF_SQLDB_COPY_CONTROL_KEY HAVING COUNT(1) > 1);
    IF (dup_count > 0) THEN
    RAISE dup_primary_key_exception;
	END IF;

    SELECT COUNT(1) INTO :dup_count 
        FROM(SELECT TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, COUNT(1) FROM UTIL.TMP_ADF_SQLDB_COPY_CONTROL GROUP BY TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH HAVING COUNT(1) > 1);
    IF (dup_count > 0) THEN
    RAISE dup_unique_key_exception;
	END IF;
END;
$$;

--Use a minus query to find any diffs and update or insert as needed
MERGE INTO UTIL.ADF_SQLDB_COPY_CONTROL AS TGT

USING (SELECT ADF_SQLDB_COPY_CONTROL_KEY, IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME, SOURCE_SCHEMA_NAME, SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME, IS_COPY_INTO_FLAG, IS_ASQL_SOURCE, SOURCE_SERVER_NAME
    FROM UTIL.tmp_adf_sqldb_copy_control
    MINUS
    SELECT ADF_SQLDB_COPY_CONTROL_KEY, IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME, SOURCE_SCHEMA_NAME, SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME, IS_COPY_INTO_FLAG, IS_ASQL_SOURCE, SOURCE_SERVER_NAME
    FROM UTIL.ADF_SQLDB_COPY_CONTROL)
    AS SRC
    
ON (
    TGT.TARGET_DATABASE_NAME = SRC.TARGET_DATABASE_NAME
    AND TGT.TARGET_SCHEMA_NAME = SRC.TARGET_SCHEMA_NAME
    AND TGT.TARGET_TABLE_NAME = SRC.TARGET_TABLE_NAME
	AND TGT.TARGET_DATA_LAKE_PATH = SRC.TARGET_DATA_LAKE_PATH
    )
    
WHEN MATCHED
THEN UPDATE
    SET TGT.ADF_SQLDB_COPY_CONTROL_KEY = SRC.ADF_SQLDB_COPY_CONTROL_KEY,
    TGT.IS_ACTIVE = SRC.IS_ACTIVE,
    TGT.LAST_UPDATED_DATETIME = CURRENT_TIMESTAMP(),
    TGT.IS_INCREMENTAL_FLAG = SRC.IS_INCREMENTAL_FLAG,
    TGT.IS_TRUNCATE_TABLE_FLAG = SRC.IS_TRUNCATE_TABLE_FLAG,
    TGT.IS_PARTITION_BY_DATE_FLAG = SRC.IS_PARTITION_BY_DATE_FLAG,
    TGT.SOURCE_DATABASE_NAME = SRC.SOURCE_DATABASE_NAME,
    TGT.SOURCE_SCHEMA_NAME = SRC.SOURCE_SCHEMA_NAME,
    TGT.SOURCE_TABLE_NAME = SRC.SOURCE_TABLE_NAME,
    TGT.SOURCE_QUERY = SRC.SOURCE_QUERY,
    TGT.SOURCE_LOOKUP_COLUMN_NAME = SRC.SOURCE_LOOKUP_COLUMN_NAME,
    TGT.SOURCE_SECRET_VALUE = SRC.SOURCE_SECRET_VALUE,
    TGT.TARGET_DATABASE_NAME = SRC.TARGET_DATABASE_NAME,
    TGT.TARGET_SCHEMA_NAME = SRC.TARGET_SCHEMA_NAME,
    TGT.TARGET_TABLE_NAME = SRC.TARGET_TABLE_NAME,
    TGT.TARGET_DATA_LAKE_PATH = SRC.TARGET_DATA_LAKE_PATH,
    TGT.ADF_TRIGGER_NAME = SRC.ADF_TRIGGER_NAME,
    TGT.IS_PARTITION_BY_STRING = SRC.IS_PARTITION_BY_STRING,
    TGT.PARTITION_BY_STRING_COLUMN_NAME = SRC.PARTITION_BY_STRING_COLUMN_NAME,
    TGT.TARGET_CONTAINER_NAME = SRC.TARGET_CONTAINER_NAME,
	TGT.IS_COPY_INTO_FLAG = SRC.IS_COPY_INTO_FLAG,
	TGT.IS_ASQL_SOURCE = SRC.IS_ASQL_SOURCE,
	TGT.SOURCE_SERVER_NAME = SRC.SOURCE_SERVER_NAME
WHEN NOT MATCHED
THEN INSERT
    (ADF_SQLDB_COPY_CONTROL_KEY, IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME, SOURCE_SCHEMA_NAME, SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME, INSERT_DATETIME, LAST_UPDATED_DATETIME, IS_COPY_INTO_FLAG, IS_ASQL_SOURCE, SOURCE_SERVER_NAME)
VALUES
    (SRC.ADF_SQLDB_COPY_CONTROL_KEY, SRC.IS_ACTIVE, SRC.IS_INCREMENTAL_FLAG,src.IS_TRUNCATE_TABLE_FLAG, src.IS_PARTITION_BY_DATE_FLAG, src.SOURCE_DATABASE_NAME, src.SOURCE_SCHEMA_NAME,     src.SOURCE_TABLE_NAME, src.SOURCE_QUERY, src.SOURCE_LOOKUP_COLUMN_NAME, src.SOURCE_SECRET_VALUE, src.TARGET_DATABASE_NAME, src.TARGET_SCHEMA_NAME, src.TARGET_TABLE_NAME, src.TARGET_DATA_LAKE_PATH, src.ADF_TRIGGER_NAME, src.IS_PARTITION_BY_STRING, src.PARTITION_BY_STRING_COLUMN_NAME, src.TARGET_CONTAINER_NAME, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.IS_COPY_INTO_FLAG, src.IS_ASQL_SOURCE, src.SOURCE_SERVER_NAME);

-- delete from target
DELETE FROM UTIL.ADF_SQLDB_COPY_CONTROL AS TGT
USING
(SELECT IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME, SOURCE_SCHEMA_NAME, SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME, IS_COPY_INTO_FLAG, IS_ASQL_SOURCE, SOURCE_SERVER_NAME
    FROM UTIL.ADF_SQLDB_COPY_CONTROL
    MINUS
    SELECT IS_ACTIVE, IS_INCREMENTAL_FLAG,IS_TRUNCATE_TABLE_FLAG, IS_PARTITION_BY_DATE_FLAG, SOURCE_DATABASE_NAME, SOURCE_SCHEMA_NAME, SOURCE_TABLE_NAME, SOURCE_QUERY, SOURCE_LOOKUP_COLUMN_NAME, SOURCE_SECRET_VALUE, TARGET_DATABASE_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME, TARGET_DATA_LAKE_PATH, ADF_TRIGGER_NAME, IS_PARTITION_BY_STRING, PARTITION_BY_STRING_COLUMN_NAME, TARGET_CONTAINER_NAME, IS_COPY_INTO_FLAG, IS_ASQL_SOURCE, SOURCE_SERVER_NAME
    FROM UTIL.tmp_adf_sqldb_copy_control) AS SRC
WHERE 
    TGT.TARGET_DATABASE_NAME = SRC.TARGET_DATABASE_NAME
    AND TGT.TARGET_SCHEMA_NAME = SRC.TARGET_SCHEMA_NAME
    AND TGT.TARGET_TABLE_NAME = SRC.TARGET_TABLE_NAME
	AND TGT.TARGET_DATA_LAKE_PATH = SRC.TARGET_DATA_LAKE_PATH
    ;